/* TODOROKI: newly composed learning material, 2026-10-29. Not copied from a magazine. */
const lessons=[{"id": "orig-20261029-01", "title": "回収と売上を分ける", "body": "掛売りを記録した後の入金は、新しい売上ではありません。売掛金を現金預金へ置き換える処理です。いつ収益を認識したかと、いつ回収したかを分けて考えます。", "tag": "商業簿記｜現金預金および債権", "topic": "現金預金および債権", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards.html", "sourceLabel": "企業会計基準一覧"}, {"id": "orig-20261029-02", "title": "運賃を含む仕入単価", "body": "商品の購入に直接必要な引取運賃を含めて取得原価を計算します。販売時の配送費とは目的が異なります。単価を出す前に、数量と取得費用の対象をそろえます。", "tag": "商業簿記｜棚卸資産", "topic": "棚卸資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=24", "sourceLabel": "棚卸資産の評価に関する会計基準"}, {"id": "orig-20261029-03", "title": "受入れと払出しの時系列", "body": "先入先出法では、先に仕入れた原価から払い出したと仮定します。最後に残る数量がどの仕入層に属するかを、数量の流れから確認します。", "tag": "商業簿記｜棚卸資産", "topic": "棚卸資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=24", "sourceLabel": "棚卸資産の評価に関する会計基準"}, {"id": "orig-20261029-04", "title": "平均単価の更新", "body": "移動平均法は、仕入れのたびに残っている原価と新規取得原価を合算し、合計数量で割ります。販売だけがあった時点では平均単価は変わりません。", "tag": "商業簿記｜棚卸資産", "topic": "棚卸資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=24", "sourceLabel": "棚卸資産の評価に関する会計基準"}, {"id": "orig-20261029-05", "title": "月割り償却の順序", "body": "定額法の計算では、取得原価から残存価額を引き、耐用年数で割って年額を出します。その後に使用月数の割合を掛けます。端数処理も条件に従います。", "tag": "商業簿記｜固定資産", "topic": "固定資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards.html", "sourceLabel": "企業会計基準一覧"}, {"id": "orig-20261029-06", "title": "外貨債務を決算日に見直す", "body": "外貨で支払う債務では、円の支払見込額が為替相場で動きます。決算換算により負債が増える場合と減る場合で、為替差損益の向きが変わります。", "tag": "商業簿記｜為替換算会計", "topic": "為替換算会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards.html", "sourceLabel": "企業会計基準一覧"}, {"id": "orig-20261029-07", "title": "社内の債権債務をそろえる", "body": "本店と支店の帳簿を合算する前に、未達の送金や商品を確認します。対応関係がそろってから、本店勘定と支店勘定などの内部残高を消去します。", "tag": "商業簿記｜本支店会計", "topic": "本支店会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards.html", "sourceLabel": "企業会計基準一覧"}, {"id": "orig-20261029-08", "title": "グループ内販売の利益", "body": "グループ内の売買でも、個別帳簿では利益が出ます。商品がグループの外へまだ販売されていなければ、連結上はその在庫に含まれる利益を調整します。", "tag": "商業簿記｜連結会計", "topic": "連結会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=111", "sourceLabel": "連結財務諸表に関する会計基準"}, {"id": "orig-20261029-09", "title": "支配獲得時の差額", "body": "連結では親会社の投資と対応する子会社資本を消去します。取得対価と取得日に評価した純資産の持分額の差を確認します。帳簿純資産をそのまま使えるとは限りません。", "tag": "商業簿記｜連結会計", "topic": "連結会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=111", "sourceLabel": "連結財務諸表に関する会計基準"}, {"id": "orig-20261029-10", "title": "利益から営業CFへ", "body": "間接法では、利益に含まれる非資金項目や運転資本の増減を調整します。売掛金の増加は、利益に含まれていても未回収である分を表します。", "tag": "商業簿記｜キャッシュ・フロー会計", "topic": "キャッシュ・フロー会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards.html", "sourceLabel": "企業会計基準一覧"}, {"id": "orig-20261029-11", "title": "利益と資金の時間差", "body": "収益・費用の認識と現金の受払は一致するとは限りません。期間損益を理解するには、受取・支払の時期だけでなく、どの期間の活動に対応するかを確認します。", "tag": "会計学｜総論", "topic": "総論", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards.html", "sourceLabel": "企業会計基準一覧"}, {"id": "orig-20261029-12", "title": "借入れと出資の違い", "body": "同じ現金の増加でも、返済義務を伴う借入れと株主からの出資では対応する項目が異なります。現金の増減だけで利益を判断しないことが重要です。", "tag": "会計学｜貸借対照表", "topic": "貸借対照表", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards.html", "sourceLabel": "企業会計基準一覧"}, {"id": "orig-20261029-13", "title": "取得原価と販売見込額", "body": "通常の販売目的の在庫では、収益性が落ちた場合の簿価切下げを検討します。販売見込額だけでなく、販売までに必要な費用も考慮します。", "tag": "会計学｜棚卸資産", "topic": "棚卸資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=24", "sourceLabel": "棚卸資産の評価に関する会計基準"}, {"id": "orig-20261029-14", "title": "認識判定と測定を分ける", "body": "日本基準の固定資産減損では、兆候の把握後、割引前の将来CFと帳簿価額を比較して損失認識を判定します。損失額の測定では回収可能価額を使います。", "tag": "会計学｜減損会計", "topic": "減損会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=83", "sourceLabel": "固定資産の減損に係る会計基準"}, {"id": "orig-20261029-15", "title": "回収の二つの道", "body": "資産を売る場合と、使い続ける場合の回収額を比べます。回収可能価額には、正味売却価額と使用価値のうち高い方を用います。", "tag": "会計学｜減損会計", "topic": "減損会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=83", "sourceLabel": "固定資産の減損に係る会計基準"}, {"id": "orig-20261029-16", "title": "見積りは新情報で変わる", "body": "利用可能な新情報で耐用年数などを見直す場合、過去の誤りの訂正とは区別します。見積り変更の影響は、その変更期と影響を受ける将来期間へ反映します。", "tag": "会計学｜総論", "topic": "総論", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards.html", "sourceLabel": "企業会計基準一覧"}, {"id": "orig-20261029-17", "title": "研究段階の費用", "body": "新しい製品を目指す支出でも、将来の成功が確実とは限りません。日本基準で研究開発費に該当する支出は、発生時の費用として扱います。", "tag": "会計学｜研究開発費等", "topic": "研究開発費等", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards.html", "sourceLabel": "企業会計基準一覧"}, {"id": "orig-20261029-18", "title": "株主への配当と費用", "body": "利益の分配である配当は、商品の販売やサービス提供のために生じた費用とは区別します。利益剰余金などの減少と、支払義務の発生を考えます。", "tag": "会計学｜純資産", "topic": "純資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards.html", "sourceLabel": "企業会計基準一覧"}, {"id": "orig-20261029-19", "title": "現在と将来の金額", "body": "将来の金額を現在価値へ直すときは、割引率と期間を対応させます。年率が正で他条件が同じなら、受取時期が遠いほど現在価値は小さくなります。", "tag": "会計学｜総論", "topic": "総論", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards.html", "sourceLabel": "企業会計基準一覧"}, {"id": "orig-20261029-20", "title": "過去の販売に伴う将来支出", "body": "製品保証では、販売済み製品に関して将来発生する合理的な見積額を確認します。売上との対応、発生可能性、見積りの根拠が重要です。", "tag": "会計学｜引当金", "topic": "引当金", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards.html", "sourceLabel": "企業会計基準一覧"}, {"id": "orig-20261029-21", "title": "材料の行き先で分ける", "body": "材料がどの製品に使われたか追跡できる場合は、その製品へ直接集計します。複数製品に共通する費用は、合理的な基準で配賦します。", "tag": "工業簿記｜費目別計算", "topic": "工原：費目別計算", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"id": "orig-20261029-22", "title": "材料消費額の数量照合", "body": "材料の消費額は、期首残高に当期仕入を加え、期末残高を引くことで確認できます。材料勘定と仕掛品などの振替先が対応しているかも確かめます。", "tag": "工業簿記｜費目別計算", "topic": "工原：費目別計算", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"id": "orig-20261029-23", "title": "配賦基準の単位", "body": "間接費の配賦額を出すには、費用額を配賦基準の総量で割って率を求め、対象製品が使った量を掛けます。時間当たりと個数当たりを混同しないようにします。", "tag": "工業簿記｜部門別計算", "topic": "工原：部門別計算", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"id": "orig-20261029-24", "title": "配賦額と実際額の差", "body": "予定配賦額は、予定率と実際操業量から計算した額です。実際発生額との差が配賦差異になります。有利・不利の符号は採用した表示方法を確認します。", "tag": "工業簿記｜部門別計算", "topic": "工原：部門別計算", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"id": "orig-20261029-25", "title": "注文別の集計", "body": "個別原価計算では注文などの単位ごとに、直接材料費・直接労務費・配賦間接費を集計します。完成時には仕掛品から製品へ、その集計額を振り替えます。", "tag": "工業簿記｜個別原価計算", "topic": "工原：個別原価計算", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"id": "orig-20261029-26", "title": "加工の完成度を換算する", "body": "月末の未完成品は、加工がどこまで進んだかで完成品換算量を求めます。材料を工程始点で投入する場合、材料と加工費では換算量が異なります。", "tag": "工業簿記｜実際総合原価計算", "topic": "工原：実際総合原価計算", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"id": "orig-20261029-27", "title": "材料費の配分", "body": "全ての材料を工程始点で投入する場合、月末仕掛品にも材料は全量投入済みです。期首仕掛品や仕損のないケースでは、完成品と月末数量の合計で材料単価を求めます。", "tag": "工業簿記｜実際総合原価計算", "topic": "工原：実際総合原価計算", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"id": "orig-20261029-28", "title": "前工程費を引き継ぐ", "body": "工程別に計算する場合、前工程で完成して次工程へ渡した原価を次工程が引き継ぎます。次工程で加えた加工費と重複集計しないようにします。", "tag": "工業簿記｜工程別総合原価計算", "topic": "工原：工程別総合原価計算", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"id": "orig-20261029-29", "title": "価格と使用量を分ける", "body": "材料の原価差異を調べるとき、単価のずれと使用量のずれを分けます。同じ差異を二重に数えないよう、どちらの数量・単価を使うか定義を固定します。", "tag": "工業簿記｜標準原価計算", "topic": "工原：標準原価計算", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"id": "orig-20261029-30", "title": "使用量の超過を測る", "body": "数量差異では、実際に生産した数量に対して許容される標準消費量を求めます。予算上の生産数量ではなく、実際生産量に対応させる点が重要です。", "tag": "工業簿記｜標準原価計算", "topic": "工原：標準原価計算", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"id": "orig-20261029-31", "title": "売上1単位の貢献", "body": "単価から単位変動費を引いた額が、1単位販売による限界利益です。固定費の回収と、その後の利益への貢献を分けて考えます。", "tag": "原価計算｜原価・営業量・利益関係分析", "topic": "工原：原価・営業量・利益関係分析", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"id": "orig-20261029-32", "title": "損益分岐点の数量", "body": "販売数量にかかわらず生じる固定費を、1単位の限界利益で回収するには何単位必要かを計算します。価格・費用が対象範囲で一定という前提です。", "tag": "原価計算｜原価・営業量・利益関係分析", "topic": "工原：原価・営業量・利益関係分析", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"id": "orig-20261029-33", "title": "目標利益から逆算する", "body": "固定費だけでなく、得たい営業利益も限界利益でまかないます。必要数量が整数でなければ、目標を満たす方向に切り上げます。", "tag": "原価計算｜原価・営業量・利益関係分析", "topic": "工原：原価・営業量・利益関係分析", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"id": "orig-20261029-34", "title": "在庫に含まれる固定製造費", "body": "全部原価計算は固定製造間接費も製品原価へ含めます。直接原価計算では当期の固定費として扱うため、在庫数量の変化で利益が異なることがあります。", "tag": "原価計算｜全部原価計算と直接原価計算", "topic": "工原：全部原価計算と直接原価計算", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"id": "orig-20261029-35", "title": "生産量と販売量をつなぐ", "body": "販売予定数量に、期末に確保したい製品在庫を加え、期首にある在庫を引くと必要生産量になります。販売予算と生産予算を混同しないことが要点です。", "tag": "原価計算｜予算編成", "topic": "工原：予算編成", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"id": "orig-20261029-36", "title": "実際操業量に合わせる", "body": "変動予算では、比較対象の操業量に合わせて変動費を計算し直します。固定費と変動費を区別したうえで実際発生額との差を確認します。", "tag": "原価計算｜予算統制", "topic": "工原：予算統制", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"id": "orig-20261029-37", "title": "特別注文の増分利益", "body": "余力がある特別注文では、受注によって増える収入と支出を比較します。既存注文への影響や追加固定費がある場合は、その分も含めます。", "tag": "原価計算｜業務的意思決定", "topic": "工原：業務的意思決定", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"id": "orig-20261029-38", "title": "過去の支出を混ぜない", "body": "既に支払って回収できない費用は、現在の選択肢間で変わらないなら差額比較から外します。ただし、売却可能額や代替用途の価値は別途検討します。", "tag": "原価計算｜業務的意思決定", "topic": "工原：業務的意思決定", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"id": "orig-20261029-39", "title": "設備案の正味現在価値", "body": "設備投資では、将来の増分CFを現在価値に換算して初期支出と比較します。利益とCF、耐用年数と評価期間、残存価値の条件を分けて確認します。", "tag": "原価計算｜構造的意思決定", "topic": "工原：構造的意思決定", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"id": "orig-20261029-40", "title": "制約資源1時間の貢献", "body": "生産能力が限られるときは、製品1個の利益だけでなく、制約となる資源1単位当たりの貢献を比べます。需要上限などがあれば配分も調整します。", "tag": "原価計算｜意思決定", "topic": "工原：意思決定", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}];
const qs=[{"q": "青波商店が前月の売掛金73,600円を普通預金に全額回収した。今回の仕訳は？", "a": ["普通預金73,600／売掛金73,600", "普通預金73,600／売上73,600", "売掛金73,600／普通預金73,600"], "correct": 0, "ex": "借方：普通預金73,600円、貸方：売掛金73,600円。前月の債権を回収したため、今回の売上にはしません。", "topic": "現金預金および債権", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards.html", "sourceLabel": "企業会計基準一覧"}, {"q": "商品48個の代金57,600円と引取運賃2,400円を支払った。他の費用や税はない。1個の取得原価は？", "a": ["1,250円", "1,200円", "1,300円"], "correct": 0, "ex": "取得原価は57,600＋2,400＝60,000円。60,000÷48＝1,250円です。販売時の運賃はこの設問には含めません。", "topic": "棚卸資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=24", "sourceLabel": "棚卸資産の評価に関する会計基準"}, {"q": "期首に12個・単価310円、当月に18個・単価340円を受け入れた後、20個を販売した。先入先出法による期末原価は？", "a": ["3,400円", "3,100円", "6,440円"], "correct": 0, "ex": "期首12個と当月8個が売れたと考えます。残りは当月仕入10個なので10×340＝3,400円。評価損は考えません。", "topic": "棚卸資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=24", "sourceLabel": "棚卸資産の評価に関する会計基準"}, {"q": "手持ち15個の原価が6,000円。9個を4,800円で追加取得し、その後6個販売した。移動平均法の期末原価は？", "a": ["8,100円", "10,800円", "7,200円"], "correct": 0, "ex": "受入後は24個・10,800円、単価450円です。6個販売後は18個なので18×450＝8,100円です。", "topic": "棚卸資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=24", "sourceLabel": "棚卸資産の評価に関する会計基準"}, {"q": "10月1日に設備を稼働。取得原価864,000円、残存価額0、耐用年数6年。翌3月末決算、月割り定額法で当期の償却費は？", "a": ["72,000円", "144,000円", "36,000円"], "correct": 0, "ex": "年額864,000÷6＝144,000円。10月から3月の6か月分は144,000×6÷12＝72,000円です。", "topic": "固定資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards.html", "sourceLabel": "企業会計基準一覧"}, {"q": "USD800の買掛金を1ドル143円で計上した。未決済のまま決算相場146円で換算する。為替差損益は？", "a": ["為替差損2,400円", "為替差益2,400円", "為替差損116,800円"], "correct": 0, "ex": "計上時114,400円、決算時116,800円。負債が2,400円増えるので、借方：為替差損2,400／貸方：買掛金2,400です。", "topic": "為替換算会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards.html", "sourceLabel": "企業会計基準一覧"}, {"q": "支店側では本店からの送金26,000円が未記帳だった。銀行への着金は確認済みで、他の未達はない。支店の修正は？", "a": ["普通預金26,000／本店26,000", "本店26,000／売上26,000", "支店26,000／普通預金26,000"], "correct": 0, "ex": "支店では預金の増加と本店に対する内部残高を記録します。本店の帳簿で送金を計上済みという前提です。", "topic": "本支店会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards.html", "sourceLabel": "企業会計基準一覧"}, {"q": "親会社が原価84,000円の商品を子会社へ105,000円で販売。子会社は期末にその40％を未販売で保有する。税効果等を除く未実現利益は？", "a": ["8,400円", "21,000円", "42,000円"], "correct": 0, "ex": "内部利益は105,000−84,000＝21,000円。その40％が在庫に残るので8,400円。連結上、利益と棚卸資産を調整します。", "topic": "連結会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=111", "sourceLabel": "連結財務諸表に関する会計基準"}, {"q": "株式100％を1,460万円で取得。取得日に時価評価済みの識別可能純資産は1,250万円。段階取得・税効果等はなく、のれんの取得時金額は？", "a": ["210万円", "1,250万円", "2,710万円"], "correct": 0, "ex": "1,460−1,250＝210万円。設問では純資産の時価評価が済んでおり、取得関連費用などの追加調整はありません。", "topic": "連結会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=111", "sourceLabel": "連結財務諸表に関する会計基準"}, {"q": "税引前利益420万円、減価償却費65万円、売掛金増加32万円、買掛金減少18万円。他の調整・利息・税支払なし。営業CFは？", "a": ["435万円", "499万円", "305万円"], "correct": 0, "ex": "420＋65−32−18＝435万円。減価償却を加え、売掛金の増加と買掛金の減少を控除します。", "topic": "キャッシュ・フロー会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards.html", "sourceLabel": "企業会計基準一覧"}, {"q": "3月に提供済みの役務代金9万円を4月に回収した。役務の収益認識要件は3月に満たす。3月の扱いは？", "a": ["収益9万円と未回収の債権を認識", "現金回収まで収益を必ず延期", "現金9万円を受領したと記録"], "correct": 0, "ex": "収益認識の要件を満たした3月に収益と債権を計上します。4月の入金時は債権の回収として処理します。", "topic": "総論", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards.html", "sourceLabel": "企業会計基準一覧"}, {"q": "他の取引がない会社が銀行から160万円を借り入れた。借入直後の純資産への影響は？", "a": ["変化なし", "160万円増加", "160万円減少"], "correct": 0, "ex": "資産の預金が160万円、負債の借入金も160万円増えます。資産−負債である純資産には影響しません。", "topic": "貸借対照表", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards.html", "sourceLabel": "企業会計基準一覧"}, {"q": "在庫の取得原価228,000円、見積売価219,000円、見積販売費13,000円。追加製造費は0。収益性低下による評価損は？", "a": ["22,000円", "9,000円", "13,000円"], "correct": 0, "ex": "正味売却価額は219,000−13,000＝206,000円。228,000−206,000＝22,000円を切り下げます。", "topic": "棚卸資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=24", "sourceLabel": "棚卸資産の評価に関する会計基準"}, {"q": "減損の兆候あり。帳簿価額930万円、割引前将来CF合計880万円、回収可能価額760万円。減損損失はいくら？", "a": ["170万円", "50万円", "0円"], "correct": 0, "ex": "880＜930なので認識します。測定は930−760＝170万円。認識判定に用いたCFとの差50万円を損失額にしない点が要点です。", "topic": "減損会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=83", "sourceLabel": "固定資産の減損に係る会計基準"}, {"q": "正味売却価額515万円、使用価値548万円。回収可能価額は？", "a": ["548万円", "515万円", "1,063万円"], "correct": 0, "ex": "高い方の548万円です。二つを合計するのではなく、売却と使用による回収の選択肢を比較します。", "topic": "減損会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=83", "sourceLabel": "固定資産の減損に係る会計基準"}, {"q": "期首帳簿価額570,000円、残存価額30,000円。新情報により残存使用期間を3年と見積もり直した。期首変更・定額法の年額は？", "a": ["180,000円", "190,000円", "540,000円"], "correct": 0, "ex": "変更時点の償却対象額570,000−30,000＝540,000円。変更後の3年で割り180,000円です。過去の償却額をこの理由だけでやり直しません。", "topic": "総論", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards.html", "sourceLabel": "企業会計基準一覧"}, {"q": "当期の研究開発に直接用いた消耗材料96,000円を全て消費した。未使用分・他用途なし。基本的な扱いは？", "a": ["当期の研究開発費96,000円", "必ず繰延資産96,000円", "売上96,000円"], "correct": 0, "ex": "研究開発費に該当する消費額を当期費用とします。将来製品が売れる見込みだけで、自由に資産計上することはできません。", "topic": "研究開発費等", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards.html", "sourceLabel": "企業会計基準一覧"}, {"q": "利益剰余金から配当18万円を適法に決議。配当原資・手続に問題なく、支払前とする。営業利益への影響は？", "a": ["影響なし", "18万円減少", "18万円増加"], "correct": 0, "ex": "配当は利益処分に関する取引で、営業費用ではありません。利益剰余金等の減少と未払配当金の計上を行います。", "topic": "純資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards.html", "sourceLabel": "企業会計基準一覧"}, {"q": "2年後に単一の入金242,000円を受け取る。年利10％・年1回複利で割り引く現在価値は？", "a": ["200,000円", "220,000円", "242,000円"], "correct": 0, "ex": "242,000÷1.1÷1.1＝200,000円。2年分なので1.1を2回割ります。信用リスク等は設問では別途考慮しません。", "topic": "総論", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards.html", "sourceLabel": "企業会計基準一覧"}, {"q": "引当金の計上要件を満たす製品保証について、期末必要額84,000円、整理前残高29,000円。差額補充の繰入額は？", "a": ["55,000円", "84,000円", "113,000円"], "correct": 0, "ex": "必要残高84,000円にするには84,000−29,000＝55,000円を追加します。必要額そのものと繰入額を区別します。", "topic": "引当金", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards.html", "sourceLabel": "企業会計基準一覧"}, {"q": "注文番号K-27だけに使う専用金具41,500円を出庫した。個別原価計算での基本的な分類は？", "a": ["直接材料費", "本社の販売費", "必ず間接労務費"], "correct": 0, "ex": "K-27との対応を追跡できる材料費です。製品別に直接集計します。金額の大小だけで直接・間接を決めません。", "topic": "工原：費目別計算", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"q": "材料の期首残高36,000円、当期仕入154,000円、期末残高42,000円。減耗・返品なし。消費額は？", "a": ["148,000円", "160,000円", "190,000円"], "correct": 0, "ex": "36,000＋154,000−42,000＝148,000円です。期末に残る材料はまだ製造に投入していないため除きます。", "topic": "工原：費目別計算", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"q": "製造間接費の予定額540,000円、予定機械時間900時間。製品Lが75時間使用した。予定配賦額は？", "a": ["45,000円", "40,500円", "7,200円"], "correct": 0, "ex": "予定配賦率540,000÷900＝600円／時間。75時間分は600×75＝45,000円です。", "topic": "工原：部門別計算", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"q": "当月の実際製造間接費286,000円、予定配賦済額272,000円。配賦不足額はいくら？", "a": ["14,000円", "558,000円", "0円"], "correct": 0, "ex": "実際発生額の方が14,000円多いため配賦不足です。この問題では不足額を正の金額で答えます。", "topic": "工原：部門別計算", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"q": "注文Mの直接材料費76,000円、直接労務費49,000円、配賦間接費35,000円。他の原価なし。完成原価は？", "a": ["160,000円", "125,000円", "84,000円"], "correct": 0, "ex": "76,000＋49,000＋35,000＝160,000円。完成すると仕掛品から製品へ振り替える対象になります。", "topic": "工原：個別原価計算", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"q": "完成品720個、月末仕掛品160個・加工進捗度25％。期首仕掛品・仕損なし。加工費の完成品換算量の合計は？", "a": ["760個", "880個", "220個"], "correct": 0, "ex": "完成品720＋仕掛品160×25％＝760個分です。材料の投入時点とは別に、加工費について計算しています。", "topic": "工原：実際総合原価計算", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"q": "材料費176,000円、完成品720個、月末仕掛品160個。材料は始点投入、期首・仕損なし。月末仕掛品の材料費は？", "a": ["32,000円", "8,000円", "144,000円"], "correct": 0, "ex": "数量合計880個、単価176,000÷880＝200円。月末160個分は32,000円。加工進捗度を材料費に掛けない条件です。", "topic": "工原：実際総合原価計算", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"q": "第2工程へ前工程費312,000円を振替。当月に材料費48,000円、加工費126,000円を追加。期首・期末仕掛品・仕損なし。第2工程完成品原価は？", "a": ["486,000円", "174,000円", "438,000円"], "correct": 0, "ex": "312,000＋48,000＋126,000＝486,000円。前工程費も完成品に含まれます。", "topic": "工原：工程別総合原価計算", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"q": "消費時点の価格差異を計算する。標準単価125円、実際単価132円、実際消費量360kg。価格差異の不利額は？", "a": ["2,520円", "45,000円", "47,520円"], "correct": 0, "ex": "（132−125）×360＝2,520円の不利差異。実際単価が高いことによる差だけを計算します。", "topic": "工原：標準原価計算", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"q": "実際生産量に対する標準消費量342kg、実際消費量360kg、標準単価125円。数量差異の不利額は？", "a": ["2,250円", "2,520円", "42,750円"], "correct": 0, "ex": "（360−342）×125＝2,250円の不利差異。単価を標準に固定して、使い過ぎの影響を取り出します。", "topic": "工原：標準原価計算", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"q": "販売単価2,400円、単位変動費1,440円。限界利益率は？", "a": ["40％", "60％", "66.7％"], "correct": 0, "ex": "限界利益は960円。960÷2,400＝40％です。変動費率60％とは区別します。", "topic": "工原：原価・営業量・利益関係分析", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"q": "単価2,400円、単位変動費1,440円、期間固定費768,000円。損益分岐点の販売数量は？", "a": ["800個", "320個", "1,280個"], "correct": 0, "ex": "単位限界利益960円。768,000÷960＝800個です。この数量では利益が0になります。", "topic": "工原：原価・営業量・利益関係分析", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"q": "単位限界利益960円、固定費768,000円、目標営業利益192,000円。必要販売数量は？", "a": ["1,000個", "800個", "200個"], "correct": 0, "ex": "（768,000＋192,000）÷960＝1,000個です。利益目標を固定費へ加えてから割ります。", "topic": "工原：原価・営業量・利益関係分析", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"q": "期首在庫0、期末在庫60個、単位固定製造間接費350円。操業度差異・原価差異等なし。全部原価計算の利益は直接原価計算よりいくら高い？", "a": ["21,000円", "350円", "0円"], "correct": 0, "ex": "期末在庫へ繰り延べられる固定製造費60×350＝21,000円だけ高くなります。期首在庫がある場合はその影響も必要です。", "topic": "工原：全部原価計算と直接原価計算", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"q": "販売予算1,850個、期首製品在庫230個、目標期末在庫310個。仕損はない。生産予算数量は？", "a": ["1,930個", "1,770個", "2,390個"], "correct": 0, "ex": "1,850＋310−230＝1,930個です。期首在庫は販売に使えるので必要生産量から引きます。", "topic": "工原：予算編成", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"q": "変動費予算率280円／時間、固定費予算160,000円、実際操業量850時間。変動予算額は？", "a": ["398,000円", "238,000円", "440,000円"], "correct": 0, "ex": "280×850＋160,000＝398,000円。実際操業量を使い、固定費は対象範囲で160,000円のままです。", "topic": "工原：予算統制", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"q": "遊休能力あり。通常販売への影響なし。追加注文140個、価格1,700円、単位増分費用1,180円、追加段取費28,000円。他の影響なし。受注による増分利益は？", "a": ["44,800円", "72,800円", "238,000円"], "correct": 0, "ex": "140×（1,700−1,180）−28,000＝44,800円。追加段取費も受注に伴う支出なので控除します。", "topic": "工原：業務的意思決定", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"q": "調査費90,000円を支払済みで返金なし。今から受注すると収入210,000円、追加支出154,000円。調査資料は他用途・売却価値なし。今からの増分利益は？", "a": ["56,000円", "マイナス34,000円", "146,000円"], "correct": 0, "ex": "210,000−154,000＝56,000円。支払済み調査費は今回の受注可否で変わらないため、今からの差額比較には入れません。", "topic": "工原：業務的意思決定", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"q": "初期支出400,000円。年末CFは1年後・2年後それぞれ242,000円。割引率10％、残存価値・税・他CFなし。正味現在価値は？", "a": ["20,000円", "84,000円", "マイナス20,000円"], "correct": 0, "ex": "242,000÷1.1＝220,000円、242,000÷1.21＝200,000円。合計420,000−400,000＝20,000円です。", "topic": "工原：構造的意思決定", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}, {"q": "機械時間だけが制約。製品Rの限界利益900円・所要3時間、製品Sは720円・所要2時間。需要は十分で他条件同じ。時間当たり限界利益が高いのは？", "a": ["製品S：360円／時間", "製品R：300円／時間", "両者同じ"], "correct": 0, "ex": "Rは900÷3＝300円、Sは720÷2＝360円。制約時間の貢献ではSを優先します。製品1個当たりの金額だけで判断しません。", "topic": "工原：意思決定", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準"}];
